                <p><?php echo esc_attr($footer_desc); ?></p>
                <?php endif; ?>
                <ul>
                    <?php if ($footer_btn_url) : ?>
                    <li class="f-btn">
                        <a href="tel:<?php echo esc_attr($footer_btn_url); ?>" class="btn-rev">
                            <?php echo esc_html($footer_btn_txt); ?></a>
                    </li>
                    <?php endif; ?>

                    <?php if ($footer_phone) : ?>
                    <li class="f-phone">
                        <a href="tel:<?php echo esc_attr($footer_phone); ?>">
                            tel./ <?php echo esc_html($footer_phone); ?></a>
                    </li>
                    <?php endif; ?>
                    <?php if ($footer_email) : ?>
                    <li class="f-email">
                        <a href="mailto:<?php echo esc_attr($footer_email); ?>">email./
                            <?php echo esc_html($footer_email); ?></a>
                    </li>
                    <?php endif; ?>

                </ul>
            </div>
        </div>

        <!-- 🔹 Kolumny 3-5: 3 menu w footerze -->
        <?php for ($i = 1; $i <= 5; $i++) :
            $menu_title = get_theme_mod("footer_menu_title_$i", '');
            $menu_id = get_theme_mod("footer_menu_$i", '');
        ?>
        <?php if ($menu_id) : ?>
        <div class="f-col">
            <div class="calaps">


                <?php if ($menu_title) : ?>
                <div class="calaps__opener">
                    <h5><?php echo esc_html($menu_title); ?></h5>
                </div>
                <?php else: ?>
                <div class="calaps__opener">
                    <span class="f-spacer"></span>
                </div>
                <?php endif; ?>
                <div class="calaps__list">
                    <?php
                            wp_nav_menu([
                                'menu' => $menu_id,
                                'container' => 'nav',
                                'container_class' => "footer-menu-$i"
                            ]);
                            ?>
                </div>

            </div>
        </div>
        <?php endif; ?>
        <?php endfor; ?>

